mapper.select:
SELECT COUNT(*)
FROM inbound
WHERE client_id = #{clientId}
  AND inbound_status = #{status}
  AND DATE (req_inbound_date) = CURDATE()

SELECT COUNT(*)
FROM outbound
WHERE client_id = #{clientId}
  AND status = #{status}
  AND DATE (req_outbound_date) = CURDATE()

SELECT COUNT(*)
FROM inbound
WHERE client_id = #{clientId}
  AND inbound_status = #{status}
  AND YEARWEEK(req_inbound_date, 1) = YEARWEEK(CURDATE(), 1)

SELECT COUNT(*)
FROM outbound
WHERE client_id = #{clientId}
  AND status = #{status}
  AND YEARWEEK(req_outbound_date, 1) = YEARWEEK(CURDATE(), 1)
